      v = self._sexpr(fb, cond)
      d = fb.temp()
      fb.emit(_n("sraw", cond["line"], {"dest": d, "src": v}))
      return d
    return self._expr(fb, cond)
  def _logic(self, fb, e, is_and):
    ln = e["line"]
    l = self._expr(fb, e["l"])
    brb = fb.cur["label"]
    rb = fb.block("rhs")
    jb = fb.block("join")
    if is_and:
      fb.end(_t("br", ln, {"cond": l, "then": rb["label"], "els": jb["label"]}))
    else:
      fb.end(_t("br", ln, {"cond": l, "then": jb["label"], "els": rb["label"]}))
    fb.start(rb)
    r = self._expr(fb, e["r"])
    rl = fb.cur["label"]
    fb.end(_t("jmp", ln, {"to": jb["label"]}))
    fb.start(jb)
    d = fb.temp()
    append(jb["instrs"], _n("phi", ln, {"dest": d, "arms": [[brb, l], [rl, r]]}))
    return d
  def _try(self, fb, s):
    ln = s["line"]
    has_except = s["ebody"] != null
    has_finally = s["fbody"] != null
    ename = pyrt.py_get(s, "ename", null)
    append(fb.trystack, {"loopdepth": len(fb.loops), "fbody": s["fbody"] if has_finally else null, "owner": pyrt.py_id(s)})
    try:
      handler = fb.block("handler")
      done = fb.block("done")
      fb.emit(_n("try_push", ln, {"handler": handler["label"]}))
      self._body(fb, s["body"])
      if fb.cur != null:
        fb.emit(_n("try_pop", ln, {}))
        if has_finally:
          self._body(fb, s["fbody"])
        fb.end(_t("jmp", ln, {"to": done["label"]}))
      fb.start(handler)
      fb.trystack[0 - 1]["caught"] = true
      if has_except:
        if has_finally:
          hfail = fb.block("hfail")
          hok = fb.block("hok")
          fb.emit(_n("try_push", ln, {"handler": hfail["label"]}))
          fb.trystack[0 - 1]["handler_guard"] = true
          self._handler_body(fb, s, ename, ln)
          if fb.cur != null:
            fb.emit(_n("try_pop", ln, {}))
            fb.end(_t("jmp", ln, {"to": hok["label"]}))
          fb.start(hfail)
          self._body(fb, s["fbody"])
          fb.emit(_n("reraise", ln, {}))
          if fb.cur != null:
            fb.end(_t("jmp", ln, {"to": hok["label"]}))
          fb.start(hok)
        else:
          self._handler_body(fb, s, ename, ln)
        if fb.cur != null:
          fb.emit(_n("exc_pop", ln, {}))
          if has_finally:
            self._body(fb, s["fbody"])
          fb.end(_t("jmp", ln, {"to": done["label"]}))
      else:
        if has_finally:
          self._body(fb, s["fbody"])
        fb.emit(_n("reraise", ln, {}))
        if fb.cur != null:
          fb.end(_t("jmp", ln, {"to": done["label"]}))
      fb.start(done)
    finally:
      fb.trystack = fb.trystack[0:len(fb.trystack) - 1]
  def _handler_body(self, fb, s, ename, ln):
    fb.exceptdepth = fb.exceptdepth + 1
    try:
      if ename != null:
        t = fb.temp()
        fb.emit(_n("exc_str", ln, {"dest": t}))
        if self._bound_in_func(fb, ename):
          old = fb.temp()
          fb.emit(_n("load", ln, {"dest": old, "name": ename}))
          fb.emit(_n("stvar", ln, {"name": ename, "src": t}))
          self._body(fb, s["ebody"])
          if fb.cur != null:
            fb.emit(_n("stvar", ln, {"name": ename, "src": old}))
        else:
          fb.emit(_n("stvar", ln, {"name": ename, "src": t}))
          self._body(fb, s["ebody"])
          if fb.cur != null:
            fb.emit(_n("unbind", ln, {"name": ename}))
      else:
        self._body(fb, s["ebody"])
    finally:
      fb.exceptdepth = fb.exceptdepth - 1
  def _bound_in_func(self, fb, name):
    if name in fb.params:
      return true
    found = [false]
    def walk(ss):
      for x in ss:
        if found[0]:
          return null
        t = x["t"]
        if t == "set" and pyrt.py_get(x, "name", null) == name:
          found[0] = true
          return null
        if t == "def":
          if pyrt.py_get(x, "name", null) == name:
            found[0] = true
          continue
        if t == "for" and pyrt.py_get(x, "var", null) == name:
          found[0] = true
          return null
        if t == "global" and name in pyrt.py_get(x, "names", []):
          found[0] = true
          return null
        for k in ["then", "els", "body", "ebody", "fbody"]:
          if pyrt.py_isinstance(pyrt.py_get(x, k, null), ["list"]):
            walk(x[k])
        for _, eb in pyrt.py_get(x, "elifs", []):
          walk(eb)
    walk(fb.ast)
    return found[0]
def build_module(prog, pfx):
  b = Builder(pfx)
  m = b.build(prog, pfx)
  iropt.optimize_module(m)
  return m
